        --bg: #0b1020;
        --panel: #11172a;
        --panel-2: #151c32;
        --border: #2a3352;
        --text: #e7ecff;
        --muted: #9aa6cb;
        --accent: #7c8cff;
        --accent-2: #a3b0ff;
        --focus: rgba(124, 140, 255, 0.35);
      }

      * {
        box-sizing: border-box;
