      }

      h1 {
        margin: 12px 0 0;
        font-size: clamp(1.8rem, 4vw, 2.4rem);
        line-height: 1.1;
      }

      .subcopy {
        margin: 12px 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .form-wrap {
        padding: 28px;
      }

