        display: grid;
        gap: 20px;
      }

      .form-field {
        padding: 20px;
        border-radius: 20px;
        background: rgba(10, 15, 29, 0.72);
        border: 1px solid var(--border);
      }

      .form-field legend {
        padding: 0;
        font-size: 1.05rem;
        font-weight: 650;
      }

      .choices {
        display: grid;
        gap: 12px;
        margin-top: 16px;
