      .choice {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 14px 16px;
        border-radius: 14px;
        background: rgba(21, 28, 50, 0.92);
        border: 1px solid transparent;
        transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
        cursor: pointer;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: rgba(163, 176, 255, 0.28);
        background: rgba(26, 34, 59, 0.96);
      }

      .choice input {
        appearance: none;
        width: 18px;
        height: 18px;
        border-radius: 999px;
        border: 2px solid #6f789d;
