          {
            onsubmit: (event) => {
              event.preventDefault();
              const selected = form.querySelector('input[name="notification-preference"]:checked');
              status.textContent = selected
                ? `Preference saved: ${selected.value}.`
                : "Please choose one notification method.";
            },
          },
          h(
