              h(
                "div",
                { className: "choices" },
                options.map((option, index) =>
                  h(
                    "label",
                    { className: "choice" },
                    h("input", {
                      type: "radio",
                      name: "notification-preference",
                      value: option,
                      required: index === 0,
                    }),
                    h("span", { textContent: option })
                  )
                )
              )
            )
