            h("h1", { id: "title", textContent: "Choose your notification channel" }),
            h(
              "p",
              {
                className: "subcopy",
                textContent:
                  "Pick a single option so we can send updates in the way that works best for you.",
              }
            )
          ),
          h("div", { className: "form-wrap" }, form)
        );

        const shell = h("div", { className: "app-shell" }, card);
        const root = document.getElementById("root");
        root.replaceChildren(shell);
        var status = form.querySelector(".status");
      }

