 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1020;
         --panel: #11172a;
         --panel-2: #151c32;
         --border: #2a3352;
         --text: #e7ecff;
         --muted: #9aa6cb;
         --accent: #7c8cff;
         --accent-2: #a3b0ff;
         --focus: rgba(124, 140, 255, 0.35);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(124, 140, 255, 0.18), transparent 34%),
           linear-gradient(180deg, #0a0f1d 0%, var(--bg) 100%);
         color: var(--text);
         display: grid;
         place-items: center;
         padding: 24px;
       }

       .app-shell {
         width: 100%;
         max-width: 560px;
       }

       .card {
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01));
         border: 1px solid rgba(163, 176, 255, 0.16);
         border-radius: 24px;
         box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
         overflow: hidden;
       }

       .card__header {
         padding: 28px 28px 0;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 8px;
         color: var(--accent-2);
         font-size: 0.875rem;
         letter-spacing: 0.04em;
         text-transform: uppercase;
       }

       .eyebrow::before {
         content: "";
         width: 10px;
         height: 10px;
         border-radius: 999px;
         background: var(--accent);
         box-shadow: 0 0 18px var(--accent);
       }

       h1 {
         margin: 12px 0 0;
         font-size: clamp(1.8rem, 4vw, 2.4rem);
         line-height: 1.1;
       }

       .subcopy {
         margin: 12px 0 0;
         color: var(--muted);
         line-height: 1.5;
       }

       .form-wrap {
         padding: 28px;
       }

       form {
         display: grid;
         gap: 20px;
       }

       .form-field {
         padding: 20px;
         border-radius: 20px;
         background: rgba(10, 15, 29, 0.72);
         border: 1px solid var(--border);
       }

       .form-field legend {
         padding: 0;
         font-size: 1.05rem;
         font-weight: 650;
       }

       .choices {
         display: grid;
         gap: 12px;
         margin-top: 16px;
       }

       .choice {
         display: flex;
         align-items: center;
         gap: 12px;
         padding: 14px 16px;
         border-radius: 14px;
         background: rgba(21, 28, 50, 0.92);
         border: 1px solid transparent;
         transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
         cursor: pointer;
       }

       .choice:hover {
         transform: translateY(-1px);
         border-color: rgba(163, 176, 255, 0.28);
         background: rgba(26, 34, 59, 0.96);
       }

       .choice input {
         appearance: none;
         width: 18px;
         height: 18px;
         border-radius: 999px;
         border: 2px solid #6f789d;
         display: grid;
         place-items: center;
         margin: 0;
         flex: 0 0 auto;
         background: rgba(255, 255, 255, 0.02);
       }

       .choice input::before {
         content: "";
         width: 9px;
         height: 9px;
         border-radius: inherit;
         transform: scale(0);
         transition: transform 150ms ease;
         background: linear-gradient(180deg, var(--accent-2), var(--accent));
       }

       .choice input:checked {
         border-color: var(--accent);
         box-shadow: 0 0 0 5px var(--focus);
       }

       .choice input:checked::before {
         transform: scale(1);
       }

       .choice input:focus-visible {
         outline: none;
         box-shadow: 0 0 0 5px var(--focus);
       }

       .choice span {
         font-size: 1rem;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 14px;
         padding: 13px 20px;
         background: linear-gradient(180deg, var(--accent-2), var(--accent));
         color: #0b1020;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 28px rgba(124, 140, 255, 0.22);
         transition: transform 160ms ease, box-shadow 160ms ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 16px 34px rgba(124, 140, 255, 0.28);
       }

       button:focus-visible {
         outline: none;
         box-shadow: 0 0 0 5px var(--focus), 0 16px 34px rgba(124, 140, 255, 0.28);
       }

       .status {
         min-height: 1.5em;
         color: var(--muted);
         font-size: 0.95rem;
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const h = (tag, props = {}, ...children) => {
         const el = document.createElement(tag);
         for (const [key, value] of Object.entries(props)) {
           if (key === "className") el.className = value;
           else if (key === "htmlFor") el.htmlFor = value;
           else if (key === "textContent") el.textContent = value;
           else if (key.startsWith("on") && typeof value === "function") {
             el.addEventListener(key.slice(2).toLowerCase(), value);
           } else if (value !== false && value != null) {
             el.setAttribute(key, value);
           }
         }
         children.flat().forEach((child) => {
           if (child == null) return;
           el.appendChild(
             child instanceof Node ? child : document.createTextNode(String(child))
           );
         });
         return el;
       };

       function App() {
         const options = ["Email", "SMS", "Push Notifications"];

         const form = h(
           "form",
           {
             onsubmit: (event) => {
               event.preventDefault();
               const selected = form.querySelector('input[name="notification-preference"]:checked');
               status.textContent = selected
                 ? `Preference saved: ${selected.value}.`
                 : "Please choose one notification method.";
             },
           },
           h(
             "div",
             { className: "form-field" },
             h(
               "fieldset",
               {},
               h("legend", { textContent: "How do you prefer to receive notifications?" }),
               h(
                 "div",
                 { className: "choices" },
                 options.map((option, index) =>
                   h(
                     "label",
                     { className: "choice" },
                     h("input", {
                       type: "radio",
                       name: "notification-preference",
                       value: option,
                       required: index === 0,
                     }),
                     h("span", { textContent: option })
                   )
                 )
               )
             )
           ),
           h(
             "div",
             { className: "actions" },
             h("button", { type: "submit", textContent: "Submit" })
           ),
           h("div", { className: "status", "aria-live": "polite", textContent: "" })
         );

         const card = h(
           "section",
           { className: "card", "aria-labelledby": "title" },
           h(
             "div",
             { className: "card__header" },
             h("div", { className: "eyebrow", textContent: "Notification settings" }),
             h("h1", { id: "title", textContent: "Choose your notification channel" }),
             h(
               "p",
               {
                 className: "subcopy",
                 textContent:
                   "Pick a single option so we can send updates in the way that works best for you.",
               }
             )
           ),
           h("div", { className: "form-wrap" }, form)
         );

         const shell = h("div", { className: "app-shell" }, card);
         const root = document.getElementById("root");
         root.replaceChildren(shell);
         var status = form.querySelector(".status");
       }

       App();
     </script>
   </body>
 </html>

